cd /Users/kenneth/.claude/projects/-Users-kenneth-Projects-JusPrin && grep -l "to our own server" *.jsonl 2>/dev/null | head; echo ---; python3 - <<'EOF'
import json,glob,re
for f in glob.glob('/Users/kenneth/.claude/projects/-Users-kenneth-Projects-JusPrin/*.jsonl'):
    try:
        for line in open(f):
            if 'to our own server' not in line: continue
            try: d=json.loads(line)
            except: continue
            if d.get('type')!='user': continue
            m=d.get('message',{}).get('content')
            texts=[]
            if isinstance(m,str): texts=[m]
            elif isinstance(m,list):
                for c in m:
                    if c.get('type')=='text': texts.append(c['text'])
                    if c.get('type')=='tool_result':
                        cc=c.get('content')
                        if isinstance(cc,str): texts.append('[TOOLRESULT] '+cc)
                        elif isinstance(cc,list):
                            for x in cc:
                                if x.get('type')=='text': texts.append('[TOOLRESULT] '+x['text'])
            for t in texts:
                i=t.find('to our own server')
                if i>=0 and len(t)<6000:
                    print(f.split('/')[-1][:8], d.get('timestamp'), '|', t[max(0,i-1500):i+600].replace('\n',' ⏎ '))
                    print('=====')
    except Exception as e: print('err',f,e)
EOF

