input.command:
python3 - <<'EOF'
import json,glob
hits=[]
for f in glob.glob('*.jsonl'):
    rows=[]
    for line in open(f):
        try: d=json.loads(line)
        except: continue
        rows.append(d)
    for i,d in enumerate(rows):
        if d.get('type')!='user': continue
        m=d.get('message',{}).get('content')
        t=None
        if isinstance(m,str): t=m
        elif isinstance(m,list):
            t=' '.join(c.get('text','') for c in m if c.get('type')=='text')
        if not t or 'own server' not in t.lower() or len(t)>1500: continue
        if not str(d.get('timestamp','')).startswith('2026-11-1'): continue
        print('FILE',f[:8],d.get('timestamp'))
        print('USER:',t)
        # previous assistant texts
        prev=[]
        j=i-1
        while j>=0 and len(prev)<3:
            p=rows[j]
            if p.get('type')=='assistant':
                for c in p.get('message',{}).get('content',[]):
                    if c.get('type')=='text' and c['text'].strip(): prev.append(c['text'])
                    if c.get('type')=='tool_use' and c.get('name') in('AskUserQuestion','mcp__ccd_turn__wrap_up'): prev.append('[TOOL '+c['name']+'] '+json.dumps(c['input'])[:3000])
            j-=1
        for p in reversed(prev): print('ASSISTANT BEFORE:',p[-3500:])
        print('==========')
EOF

