input.command:
python3 - <<'EOF'
import json,glob
for f in glob.glob('*.jsonl'):
    rows=[]
    for line in open(f):
        if 'Sentry' not in line and 'own server' not in line: continue
        try: d=json.loads(line)
        except: continue
        ts=str(d.get('timestamp',''))
        if not (ts.startswith('2026-11-15') or ts.startswith('2026-11-14') or ts.startswith('2026-11-16')): continue
        m=d.get('message',{}).get('content')
        if not isinstance(m,list): continue
        for c in m:
            if c.get('type')=='tool_use' and c.get('name')=='AskUserQuestion':
                s=json.dumps(c['input'])
                if 'server' in s and ('Sentry' in s):
                    print('ASK',f[:8],ts); print(s[:5000]); print('---')
            if c.get('type')=='tool_result':
                cc=c.get('content')
                s=cc if isinstance(cc,str) else ' '.join(x.get('text','') for x in cc if isinstance(x,dict))
                if 'own server' in s.lower() and len(s)<3000 and 'answer' in s.lower():
                    print('ANSWER',f[:8],ts); print(s[:3000]); print('---')
EOF

