    47	// cookie goes with it.
    48	struct Uploads
    49	{
    50	    SentryDsn               dsn;
    51	    std::mutex              mutex;
    52	    std::condition_variable idle;
    53	    int                     pending = 0;
    54	};
    55	
    56	void upload_done(Uploads& uploads)
    57	{
    58	    std::lock_guard<std::mutex> lock(uploads.mutex);
    59	    --uploads.pending;
    60	    uploads.idle.notify_all();
    61	}
    62	
    63	void send_envelope(sentry_envelope_t* envelope, void* state)
    64	{
    65	    Uploads&    uploads = *static_cast<Uploads*>(state);
    66	    std::size_t size    = 0;
    67	    char*       body    = sentry_envelope_serialize(envelope, &size);
    68	    sentry_envelope_free(envelope);
    69	    std::string payload(body, size);
    70	    sentry_free(body);
    71	    {
    72	        std::lock_guard<std::mutex> lock(uploads.mutex);
    73	        ++uploads.pending;
    74	    }
    75	    Slic3r::Http::post(uploads.dsn.envelope_url)
    76	        .header("User-Agent", Updates::user_agent())
    77	        .header("Content-Type", "application/x-sentry-envelope")
    78	        .header("X-Sentry-Auth", sentry_auth_header(uploads.dsn, std::string("jusprin.app/") + Updates::kVersion))
    79	        .set_post_body(payload)
    80	        .tls_verify(true)
    81	        .timeout_connect(10)
    82	        .timeout_max(30)
    83	        .on_complete([&uploads](std::string, unsigned) { upload_done(uploads); })
    84	        .on_error([&uploads](std::string body, std::string error, unsigned status) {
    85	            BOOST_LOG_TRIVIAL(error) << "JusPrin could not send an error report to " << uploads.dsn.envelope_url << " (" << status
    86	                                     << "): " << error << " " << body;
    87	            upload_done(uploads);
    88	        })
    89	        .perform();
    90	}
    91	
    92	// Waits for the uploads under way, at most `timeout` milliseconds; 0 when
    93	// none is left.
    94	int wait_for_uploads(uint64_t timeout, void* state)
    95	{
    96	    Uploads&                     uploads = *static_cast<Uploads*>(state);
    97	    std::unique_lock<std::mutex> lock(uploads.mutex);
    98	    return uploads.idle.wait_for(lock, std::chrono::milliseconds(timeout), [&uploads] { return uploads.pending == 0; }) ? 0 : 1;
    99	}
   100	
   101	// This run's log file (GUI_App's set_log_path_and_level names it after the
   102	// process id); none when the system writes no log file.
   103	std::optional<std::filesystem::path> log_file(const std::string& data_dir)
   104	{
   105	    const std::filesystem::path folder = std::filesystem::u8path(data_dir) / "log";
   106	    if (!std::filesystem::is_directory(folder))
   107	        return std::nullopt;
   108	    const std::string ending = "_" + std::to_string(get_current_pid()) + ".log.0";
   109	    for (const std::filesystem::directory_entry& entry : std::filesystem::directory_iterator(folder)) {
   110	        const std::string name = entry.path().filename().string();
   111	        if (name.size() > ending.size() && name.compare(name.size() - ending.size(), ending.size(), ending) == 0)
   112	            return entry.path();
   113	    }
   114	    return std::nullopt;
   115	}
   116	
   117	} // namespace
   118	
   119	void start_sentry(const std::string& data_dir, bool reports_automatically)
   120	{
   121	    if (g_started)
   122	        return;
   123	    const std::optional<SentryDsn> dsn = parse_sentry_dsn(sentry_dsn());
   124	    if (!dsn) {
   125	        BOOST_LOG_TRIVIAL(warning) << "JusPrin sends no error reports or crashes: this build has no Sentry project to send them to";
   126	        return;
   127	    }
   128	    // Lives as long as the app: the SDK may send until the process ends.
   129	    auto* uploads = new Uploads{*dsn};
   130	    sentry_transport_t* transport = sentry_transport_new(send_envelope);
   131	    sentry_transport_set_state(transport, uploads);
   132	    sentry_transport_set_flush_func(transport, wait_for_uploads);
   133	    sentry_transport_set_shutdown_func(transport, wait_for_uploads);
   134	
   135	    // crashpad_handler ships beside the app's executable
   136	    // (JusPrin/CMakeLists.txt).
   137	    const std::filesystem::path handler = std::filesystem::path(boost::dll::program_location().native()).parent_path() /
   138	#ifdef _WIN32
   139	                                          "crashpad_handler.exe";
   140	#else
   141	                                          "crashpad_handler";
   142	#endif
   143	    const std::filesystem::path database = std::filesystem::u8path(data_dir) / "jusprin-sentry";
   144	
   145	    sentry_options_t* options = sentry_options_new();
   146	    sentry_options_set_dsn(options, sentry_dsn().c_str());
   147	    sentry_options_set_release(options, Updates::version_label().c_str());
   148	    sentry_options_set_transport(options, transport);
   149	    sentry_options_set_require_user_consent(options, 1);
   150	#ifdef _WIN32
   151	    sentry_options_set_handler_pathw(options, handler.wstring().c_str());
   152	    sentry_options_set_database_pathw(options, database.wstring().c_str());
   153	#else
   154	    sentry_options_set_handler_path(options, handler.string().c_str());
   155	    sentry_options_set_database_path(options, database.string().c_str());
   156	#endif
   157	    // Every report and crash carries this run's log.
   158	    if (const std::optional<std::filesystem::path> log = log_file(data_dir)) {
   159	#ifdef _WIN32
   160	        sentry_options_add_attachmentw(options, log->wstring().c_str());
   161	#else
   162	        sentry_options_add_attachment(options, log->string().c_str());
   163	#endif
   164	    }
   165	    if (sentry_init(options) != 0) {
   166	        BOOST_LOG_TRIVIAL(error) << "JusPrin could not start Sentry's SDK; it sends no error reports or crashes";
   167	        return;
   168	    }
   169	    g_started = true;
   170	    sentry_follow_setting(reports_automatically);
   171	    // Sends what is still under way when the app quits.
   172	    std::atexit([] { sentry_close(); });
   173	}
   174	
   175	void sentry_follow_setting(bool reports_automatically)
   176	{
   177	    if (!g_started)
   178	        return;
   179	    if (reports_automatically)
   180	        sentry_user_consent_give();
   181	    else
   182	        sentry_user_consent_revoke();
   183	}
   184	
   185	void sentry_send(const ErrorReport& report, bool reports_automatically)
   186	{
   187	    if (!g_started) {
   188	        BOOST_LOG_TRIVIAL(error) << "JusPrin could not send an error report: Sentry's SDK is not running";
   189	        return;
   190	    }
   191	    sentry_value_t event = sentry_event(report);
   192	    // Where the app reported it; a page's event has the page's own stack.
   193	    if (report.page_event.empty())
   194	        sentry_event_value_add_stacktrace(event, nullptr, 0);
   195	    if (reports_automatically) {
   196	        sentry_capture_event(event);
   197	        return;
   198	    }
   199	    // The SDK decides when it captures, so consent given now covers this
   200	    // event only.
   201	    sentry_user_consent_give();
   202	    sentry_capture_event(event);
   203	    sentry_user_consent_revoke();
   204	}
   205	
   206	void sentry_breadcrumb(const char* category, const std::string& message)
   207	{
   208	    if (!g_started)
   209	        return;
   210	    sentry_value_t crumb = sentry_value_new_breadcrumb("default", message.c_str());
   211	    sentry_value_set_by_key(crumb, "category", sentry_value_new_string(category));
   212	    sentry_add_breadcrumb(crumb);
   213	}
   214	
   215	} // namespace Slic3r::GUI::JusPrin

