    10	#include <string>
    11	#include <vector>
    12	
    13	namespace Slic3r::GUI::JusPrin {
    14	
    15	namespace {
    16	
    17	// Sentry keeps at most 200 characters of a tag's value; cutting at as many
    18	// bytes, on a character boundary, keeps within it.
    19	std::string tag_value(std::string text)
    20	{
    21	    constexpr std::size_t limit = 200;
    22	    if (text.size() > limit) {
    23	        std::size_t end = limit;
    24	        while (end > 0 && (static_cast<unsigned char>(text[end]) & 0xC0) == 0x80)
    25	            --end;
    26	        text.resize(end);
    27	    }
    28	    return text;
    29	}
    30	
    31	// The object under `key`, made when there is none.
    32	sentry_value_t object_at(sentry_value_t parent, const char* key)
    33	{
    34	    sentry_value_t child = sentry_value_get_by_key(parent, key);
    35	    if (sentry_value_get_type(child) != SENTRY_VALUE_TYPE_OBJECT) {
    36	        sentry_value_set_by_key(parent, key, sentry_value_new_object());
    37	        child = sentry_value_get_by_key(parent, key);
    38	    }
    39	    return child;
    40	}
    41	
    42	} // namespace
    43	
    44	std::optional<SentryDsn> parse_sentry_dsn(const std::string& dsn)
    45	{
    46	    // <scheme>://<key>[:<secret>]@<host>[:<port>][/<path>]/<project>
    47	    static const std::regex shape(R"(^(https?)://([^:@/]+)(?::[^@/]*)?@([^/]+)(/(?:[^/]+/)*)([0-9]+)/?$)");
    48	    std::smatch part;
    49	    if (!std::regex_match(dsn, part, shape))
    50	        return std::nullopt;
    51	    return SentryDsn{part[1].str() + "://" + part[3].str() + part[4].str() + "api/" + part[5].str() + "/envelope/", part[2].str()};
    52	}
    53	
    54	std::string sentry_auth_header(const SentryDsn& dsn, const std::string& client)
    55	{
    56	    return "Sentry sentry_version=7, sentry_client=" + client + ", sentry_key=" + dsn.public_key;
    57	}
    58	
    59	std::vector<std::string> sentry_fingerprint(const ErrorReport& report)
    60	{
    61	    static const std::regex request_ids(R"( \(request [^()]*\)|"request_id"\s*:\s*"[^"]*")");
    62	    return {report.doing, std::regex_replace(report.error, request_ids, "")};
    63	}
    64	
    65	sentry_value_t sentry_event(const ErrorReport& report)
    66	{
    67	    sentry_value_t event;
    68	    if (report.page_event.empty()) {
    69	        event = sentry_value_new_message_event(SENTRY_LEVEL_ERROR, "jusprin.app", report.error.c_str());
    70	    } else {
    71	        event = sentry_value_from_json(report.page_event.data(), report.page_event.size());
    72	    }
    73	    sentry_value_set_by_key(event, "release", sentry_value_new_string(report.app.c_str()));
    74	
    75	    sentry_value_t tags = object_at(event, "tags");
    76	    sentry_value_set_by_key(tags, "doing", sentry_value_new_string(tag_value(report.doing).c_str()));
    77	    sentry_value_set_by_key(tags, "os", sentry_value_new_string(tag_value(report.os).c_str()));
    78	
    79	    sentry_value_t extra = object_at(event, "extra");
    80	    sentry_value_set_by_key(extra, "doing", sentry_value_new_string(report.doing.c_str()));
    81	    sentry_value_set_by_key(extra, "error", sentry_value_new_string(report.error.c_str()));
    82	    sentry_value_set_by_key(extra, "where", sentry_value_new_string(report.where.c_str()));
    83	
    84	    sentry_value_t fingerprint = sentry_value_new_list();
    85	    for (const std::string& part : sentry_fingerprint(report))
    86	        sentry_value_append(fingerprint, sentry_value_new_string(part.c_str()));
    87	    sentry_value_set_by_key(event, "fingerprint", fingerprint);
    88	    return event;
    89	}
    90	
    91	} // namespace Slic3r::GUI::JusPrin
