     1	// The top of a page's own code (AGENTS.md, Error handling): Sentry's browser
     2	// SDK catches what nothing else did -- an uncaught error, a rejected promise --
     3	// and builds its event with the stack, the recent steps and the page's
     4	// context. The event is not sent from here: it goes to the app as a
     5	// report_error message, and the app asks the person, or not when automatic
     6	// reports are on, and sends it with its own Sentry SDK (Support/SentryClient).
     7	// The page holds no Sentry project and never reaches the network for this.
     8	import { SDK_VERSION, createTransport, init, type ErrorEvent, type EventHint } from '@sentry/browser';
     9	
    10	// What a page sends the app: the two lines the report dialog shows, and the
    11	// event Sentry receives.
    12	export interface PageErrorReport {
    13	  error: string;
    14	  where: string;
    15	  event: ErrorEvent;
    16	}
    17	
    18	// The SDK runs only with a DSN. This one names no host that exists, and the
    19	// transport below never sends: every event leaves through beforeSend.
    20	const NOWHERE = 'https://page@jusprin.invalid/0';
    21	
    22	let started = false;
    23	// The page's bridge client, which holds a report until the app can take it.
    24	let deliverTo: (report: PageErrorReport) => void = () => {};
    25	
    26	export function reportOf(event: ErrorEvent, hint: EventHint): PageErrorReport {
    27	  // What the SDK itself does to an event as it sends it, which here it never
    28	  // does: names itself, and drops its own working data.
    29	  event.sdk = { ...event.sdk, name: 'sentry.javascript.browser', version: SDK_VERSION };
    30	  delete event.sdkProcessingMetadata;
    31	  const original = hint.originalException;
    32	  if (original instanceof Error) {
    33	    return { error: `${original.name}: ${original.message}`, where: original.stack ?? '', event };
    34	  }
    35	  const exception = event.exception?.values?.at(-1);
    36	  const error = exception ? `${exception.type ?? 'Error'}: ${exception.value ?? ''}` : String(original);
    37	  return { error, where: '', event };
    38	}
    39	
    40	// Starts catching, once per page, with every integration the SDK has by
    41	// default; `deliver`, the latest bridge client's, hands each report to the app.
    42	export function startErrorReports(deliver: (report: PageErrorReport) => void): void {
    43	  deliverTo = deliver;
    44	  if (started) return;
    45	  started = true;
    46	  init({
    47	    dsn: NOWHERE,
    48	    transport: (options) => createTransport(options, () => Promise.resolve({})),
    49	    beforeSend(event, hint) {
    50	      deliverTo(reportOf(event, hint));
    51	      return null;
    52	    },
    53	  });
    54	}
